/* all points of a letter, for fireworks and outlines */
function letterPoints(ch, step){
  const strokes = ST[ch]; if(!strokes) return [];
  const pts=[]; step = step||3;
  for(const s of strokes){
    if(s.dot){ pts.push(s.dot); continue; }
    for(let i=0;i<s.length;i+=step) pts.push(s[i]);
    pts.push(s[s.length-1]);
  }
  return pts;
}
function strokePath(points){ return points.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(''); }


