  const fit = ref => { const out = []; let p = 0; for (const s of ref) { out.push(word.substr(p, s.length)); p += s.length; } return p === word.length ? out : [word]; };
  if (SYL_OVR[low]) return fit(SYL_OVR[low].split('|'));
