  requestAnimationFrame(() => requestAnimationFrame(() => { s.style.transform = `translate(${b.left + 10 - a.left - a.width / 2 + 21}px,${b.top + 2 - a.top - a.height / 2 + 21}px) scale(.7)`; }));
