/* ======================= rounds ======================= */
function makeRound(id, n, opts) {
  opts = opts || {};
  const g = App.gen;
  const R = window.__R = { id, n, i: 0, first: 0, misses: 0, stars: 0, streak: 0, wrongNow: 0, locked: false, done: false, diff: opts.diff || 1, ask: opts.ask || null, params: opts.params || {}, info: opts.info || null };
  R.dots = h('div', { class: 'dots', 'aria-hidden': 'true' });
  if (App.params && App.params.tog) setTimeout(() => { if (App.alive(g) && !R.tog && typeof togEnsure === 'function') togEnsure(R); }, 80);
  R.paint = () => { R.dots.innerHTML = ''; for (let k = 0; k < R.n; k++) R.dots.appendChild(h('i', { class: k < R.i ? 'done' : k === R.i ? 'now' : '' })); };
  R.start = () => {
    R.paint();
    if (typeof togEnsure === 'function') togEnsure(R);
    if (!R.race && !R.tog && !RACE_OFF[id] && S.botsGames !== false && R.n >= 4 && typeof BotRace === 'function') {
      try { R.race = BotRace(R); if (R.dots.isConnected) R.dots.after(R.race.el); else { const s = $('#stage .screen'); if (s) s.prepend(R.race.el); else R.race = null; } } catch (e) { R.race = null; }
    }
    if (R.ask) R.ask(R.i, R);
  };
  R.finish = () => { if (R.done) return; R.done = true; if (typeof togEnsure === 'function' && togEnsure(R)) { R.doneMs = Date.now() - R.tog.t0; R.tog.pub(); } if (R.onFinish) { try { R.onFinish(); } catch (e) { } } endRound(R); };
  R.good = (el, key, o) => {
    o = o || {};
    if (R.locked || R.done) return false;
    const first = R.wrongNow === 0;
    if (key && first) Brain.rec(key, true);
    if (el && el.classList) { el.classList.remove('hint', 'no'); el.classList.add('ok'); FX.burstAt(el, { n: 22 }); }
    AE.play(o.sfx || 'ok');
    if (first) {
      R.first++; R.streak++; R.stars++; addStars(1, el);
      if (R.streak % 5 === 0) { setTimeout(() => AE.play('combo'), 260); R.stars++; setTimeout(() => addStars(1, el), 420); toast(R.streak + ' richtig hintereinander! +1'); }
    } else R.streak = 0;
    R.i++; R.wrongNow = 0; R.paint(); if (R.race) R.race.step(first); if (R.tog) { if (first) R.tog.res(1); else R.tog.pub(); }
    const sp = o.say ? Nur.say(o.say, { keep: false }) : (o.praise === false ? null : (Math.random() < 0.6 ? Nur.praise() : null));
    R.locked = true;
    const minWait = o.wait != null ? o.wait : 950;
    Promise.all([Promise.race([sp || Promise.resolve(), sleep(o.maxWait || 4800)]), sleep(minWait)]).then(async () => {
      if (!App.alive(g)) return;
      /* the bots take their turn here: Nur first, then one bot (sometimes two chatting), then the next question */
      if (R.race && R.race.playTurn && R.i < R.n) { try { await Promise.race([R.race.playTurn(), sleep(7000)]); } catch (e) { } if (!App.alive(g)) return; }
      R.locked = false;
      if (R.i >= R.n) R.finish(); else if (R.ask) R.ask(R.i, R);
    });
    return true;
  };
  R.bad = (el, key, chosen, okEl, o) => {
    o = o || {};
    if (R.locked || R.done) return;
    R.wrongNow++; R.misses++; R.streak = 0; if (R.tog && R.wrongNow === 1) R.tog.res(0);
    if (key && R.wrongNow === 1) Brain.rec(key, false, chosen);
    if (el && el.classList) { el.classList.remove('no'); void el.offsetWidth; el.classList.add('no'); }
    AE.play('no');
    if (o.say) Nur.say(o.say, { keep: false });
    if (R.wrongNow >= 2 && okEl) okEl.classList.add('hint');
  };
  return R;
}
let pendingGift = false;
