  App.later(() => { AE.play('win'); FX.confetti(big === 3 ? 90 : 50); addStars(bonus, starsEl); }, 380 + big * 420);
  const arTxt = big === 3 ? 'كل شي صح! برافو عليكي!' : big === 2 ? 'كتير منيح! شاطرة!' : 'تمرّنتي منيح! كل مرة بتصيري أشطر.';
  const tiredSay = tired ? [D('Probier jetzt ein anderes Spiel, dort gibt es wieder mehr Sterne!')] : [];
  if (tired) App.later(() => toast('Ein anderes Spiel bringt wieder mehr Sterne!'), 1600);
