/* ======================= daily journey ======================= */
const Daily = {
  get() {
    if (!S.daily || S.daily.date !== today()) { S.daily = { date: today(), l: nextLetter(), done: [0, 0, 0], gift: 0 }; Store.save(); }
    if (!S.daily.g3) { S.daily.g3 = unlocked('geschichten') ? 'geschichten' : 'blasen'; Store.save(); }
    return S.daily;
  },
  steps() {
    const d = this.get(), L = LETTERS[d.l] || LETTERS.m;
    return [
      { game: 'garten', params: { l: d.l }, de: `Buchstabe ${L.U} ${L.k}`, ar: 'حرف اليوم' },
      { game: 'schreiben', params: { l: d.l }, de: `${L.k} schreiben`, ar: 'نكتب الحرف' },
      d.g3 === 'geschichten' ? { game: 'geschichten', params: {}, de: 'Eine Geschichte', ar: 'قصة' } : { game: 'blasen', params: { l: d.l }, de: `${L.k}-Blasen`, ar: 'فقاعات الحرف' }
    ];
  },
  mark(game, info) {
    const d = this.get(), st = this.steps(); let ch = false;
    st.forEach((s, i) => {
      if (d.done[i] || s.game !== game) return;
      if (s.params.l && info && info.l && info.l !== s.params.l) return;
      d.done[i] = 1; ch = true;
      if (i === 0) { S.introduced = S.introduced || {}; S.introduced[d.l] = 1; }
    });
    if (ch) { Store.save(); if (d.done.every(Boolean) && !d.gift) pendingGift = true; }
  },
  next() { const d = this.get(), st = this.steps(), i = d.done.findIndex(x => !x); return i < 0 ? null : st[i]; }
};
function showGift(next) {
  const d = Daily.get(); if (d.gift) { next && next(); return; }
  const box = h('button', { class: 'giftbox', html: ICON.gift, 'aria-label': 'Geschenk öffnen' });
  const txt = h('p', { class: 'story-txt' }, 'Du hast heute alle drei Schritte geschafft! Tippe auf das Geschenk.');
  box.onclick = () => {
    if (d.gift) return; d.gift = 1;
    const item = pick(DECO.filter(x => x[3] <= 15 && !DECO_SKY[x[0]]));
    if (!Array.isArray(S.deco)) S.deco = [];
    S.deco.push({ id: item[0], x: 0.36 + Math.random() * 0.3, y: 0.76 + Math.random() * 0.14, s: 1 });
    Store.save();
    box.classList.add('open'); AE.play('unlock'); FX.burstAt(box, { n: 50, speed: 7 }); FX.confetti(90);
    addStars(5, box);
    txt.textContent = `+5 Sterne und ein Geschenk für dein Schloss: ${item[1]}`;
    const gp = photoEl('i_' + item[0], item[7], 'giftpic'); txt.after(gp);
    Nur.say([D('Super! Du bekommst fünf Sterne und ein Geschenk für dein Schloss:'), D(item[1]), ...arOn(A('برافو! أخدتي خمس نجوم وهدية لقصرك:'), A(item[2]))]);
  };
  Sheet.open(h('div', { class: 'col center' }, box, txt), { title: 'Tagesgeschenk', icon: ICON.gift, onClose: next });
  Nur.say([D('Ein Geschenk für dich! Tippe darauf!'), ...arIf('في هدية إلك! اضغطي عليها!')]);
}

/* ======================= time & breaks ======================= */
const Clock = {
  session: 0, lastBreak: 0, limitShown: false,
  start() { setInterval(() => this.tick(), 5000); },
  tick() {
    if (document.hidden || !CUR || App.cur === 'start' || App.cur === 'parent') return;
    if (S.dayDate !== today()) { S.dayDate = today(); S.dayMs = 0; S.extraMin = 0; this.limitShown = false; }
    S.dayMs += 5000; this.session += 5000; Store.save();
    const lim = S.limitMin ? (S.limitMin + (S.extraMin || 0)) * 60000 : 0;
    if (lim && S.dayMs >= lim && !this.limitShown) { this.limitShown = true; showLimit(); return; }
    if (S.breakOn && this.session - this.lastBreak >= 15 * 60000 && !Sheet.isOpen()) { this.lastBreak = this.session; showBreak(); }
  }
};
function showBreak() {
  const idea = pick(BREAK_IDEAS);
  const go = h('button', { class: 'btn gold', disabled: true }, h('span', { html: ICON.play }), 'Weiter');
  const ring = h('div', { class: 'break-ring' }, '15');
  Sheet.open(h('div', { class: 'col center' }, h('div', { class: 'break-ico', html: ICON.leaf }), h('p', { class: 'h2 center-txt' }, idea[0]), h('p', { class: 'ar muted center-txt' }, idea[1]), ring, go),
    { title: 'Kleine Pause', icon: ICON.clock, modal: true, noClose: true });
  Nur.say([D('Zeit für eine kleine Pause!'), D(idea[0]), ...arOn(A('وقت استراحة صغيرة!'), A(idea[1]))], { bubble: true });
  let n = 15; const t = setInterval(() => { n--; ring.textContent = String(Math.max(0, n)); if (n <= 0) { clearInterval(t); go.disabled = false; AE.play('chime'); } }, 1000);
  go.onclick = () => { clearInterval(t); AE.play('tap'); Sheet.close(); };
}
function showLimit() {
  Speech.stop();
  const more = h('button', { class: 'btn soft small' }, h('span', { html: ICON.lock }), 'Eltern: +10 Minuten');
  const bye = h('button', { class: 'btn gold' }, 'Tschüss!');
  Sheet.open(h('div', { class: 'col center' }, h('div', { class: 'break-ico', html: ICON.clock }),
    h('p', { class: 'h2 center-txt' }, 'Für heute ist die Lesezeit vorbei. Morgen geht es weiter!'), h('p', { class: 'ar muted center-txt' }, 'خلص وقت القراءة لليوم. بكرا منكمّل!'), h('div', { class: 'row' }, bye, more)),
    { title: 'Genug für heute', icon: ICON.clock, modal: true, noClose: true });
  Nur.say([D('Für heute ist die Lesezeit vorbei. Morgen geht es weiter!'), ...arIf('خلص وقت القراءة لليوم. بكرا منكمّل!')], { bubble: true });
  bye.onclick = () => { Sheet.close(true); App.go('start'); };
  more.onclick = () => parentGate(() => { S.extraMin = (S.extraMin || 0) + 10; Clock.limitShown = false; Store.save(); toast('+10 Minuten'); });
}

