/* ======================= parents ======================= */
function parentGate(onPass) {
  let a = 0, b = 0, val = '';
  const q = h('div', { class: 'h2 center-txt' }), qa = h('div', { class: 'ar muted center-txt' });
  const show = h('div', { class: 'gate-show' }, '');
  const fresh = () => { a = 3 + rnd(7); b = 3 + rnd(7); val = ''; q.textContent = `Für Eltern: Wie viel ist ${a} × ${b}?`; qa.textContent = `للأهل: قدّيش ${a} × ${b}؟`; show.textContent = '?'; };
  fresh();
  const pad = h('div', { class: 'keypad' });
  ['1', '2', '3', '4', '5', '6', '7', '8', '9', '⌫', '0', 'OK'].forEach(k => {
    const btn = h('button', { class: k === 'OK' ? 'ok' : '' }, k);
    btn.onclick = () => {
      AE.play('click');
      if (k === '⌫') val = val.slice(0, -1);
      else if (k === 'OK') {
        if (val && +val === a * b) { Sheet.onClose = null; Sheet.close(); onPass(); return; }
        show.classList.remove('no'); void show.offsetWidth; show.classList.add('no'); AE.play('no'); setTimeout(fresh, 450); return;
      } else if (val.length < 3) val += k;
      show.textContent = val || '?';
    };
    pad.appendChild(btn);
  });
  Sheet.open(h('div', { class: 'col' }, q, qa, show, pad), { title: 'Elternbereich', icon: ICON.lock });
}
function openVideos() {
  const list = h('div', { class: 'linklist' });
  VIDEOS.forEach(v => list.appendChild(h('a', { href: v.u, target: '_blank', rel: 'noopener noreferrer' }, h('b', {}, v.t), h('span', {}, v.d), h('span', { class: 'ar' }, v.da))));
  Sheet.open(h('div', { class: 'col' },
    h('p', { class: 'note' }, 'Alle Links öffnen außerhalb der App. Am besten gemeinsam ansehen: zuerst auf Deutsch, danach – wenn nötig – dieselbe Geschichte auf Arabisch. Für eigene Video-Listen ist YouTube Kids mit Eltern-Freigabe am sichersten.'),
    h('p', { class: 'note ar' }, 'كل الروابط بتنفتح برّا التطبيق. الأفضل تشوفوها سوا: أول بالألماني، وبعدين إذا لزم نفس القصة بالعربي.'), list), { title: 'Kino – für Eltern', icon: ICON.film });
}
function psec(title, ar, ...kids) { return h('section', { class: 'psec' }, h('h3', {}, h('span', {}, title), h('span', { class: 'ar' }, ar)), ...kids); }
function toggleRow(label, sub, key, onChange) {
  const b = h('button', { class: 'toggle', role: 'switch', 'aria-checked': String(!!S[key]) }, h('span', { class: 'tlabel' }, h('b', {}, label), sub ? h('small', {}, sub) : null), h('span', { class: 'sw' }));
  b.onclick = () => { S[key] = !S[key]; b.setAttribute('aria-checked', String(!!S[key])); Store.save(); AE.play('click'); if (onChange) onChange(S[key]); };
  return b;
}
function fieldText(label, val, onInput, ph, dir) {
  const inp = h('input', { type: 'text', maxlength: '20', autocomplete: 'off', spellcheck: 'false', placeholder: ph || '', dir: dir || null });
  inp.value = val || '';
  inp.addEventListener('input', () => onInput(inp.value));
  return h('div', { class: 'field' }, h('label', {}, label), inp);
}
function fieldSelect(label, options, val, onChange) {
  const sel = h('select', {});
  options.forEach(([v, t]) => { const o = h('option', { value: String(v) }, t); if (String(v) === String(val)) o.selected = true; sel.appendChild(o); });
  sel.addEventListener('change', () => onChange(sel.value));
  return h('div', { class: 'field' }, h('label', {}, label), sel);
}
function confirmBtn(label, sure, fn) {
  let armed = false, t = null;
  const b = h('button', { class: 'btn soft small danger' }, label);
  b.onclick = () => { if (!armed) { armed = true; b.textContent = sure; clearTimeout(t); t = setTimeout(() => { armed = false; b.textContent = label; }, 4000); return; } clearTimeout(t); fn(); };
  return b;
}
