function progressSection() {
  const known = LETTER_ORDER.filter(l => Brain.box('L:' + l) >= 3).length;
  const rows = LETTER_ORDER.map(l => {
    const it = S.items['L:' + l], acc = it && it.n ? it.ok / it.n : null, tr = S.traced[l] || {};
    return h('tr', {}, h('td', {}, h('b', {}, LETTERS[l].U + ' ' + l)), h('td', {}, it ? `${Math.round(acc * 100)} %` : '–'), h('td', {}, h('div', { class: 'bar' }, h('i', { style: { width: (acc == null ? 0 : Math.round(acc * 100)) + '%' } }))),
      h('td', {}, it ? String(it.n) : '0'), h('td', {}, (tr.up ? 'A' : '') + (tr.lo ? 'a' : '') || '–'));
  });
  const conf = Object.entries(S.conf).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([k, n]) => { const [x, y] = k.split('>'); return `${x.slice(2)} → ${y.slice(2)}: ${n}×`; });
  const done = Object.keys(S.storiesDone || {}).length;
  return psec('Fortschritt', 'التقدّم',
    h('p', { class: 'note' }, `Sterne gesammelt: ${S.earned} · Buchstaben sicher: ${known} von ${LETTER_ORDER.length} · Geschichten gelesen: ${done} · Lesestufe: ${readLevel()}`),
    conf.length ? h('p', { class: 'note' }, 'Häufige Verwechslungen (gefragt → getippt): ' + conf.join(' · ')) : null,
    h('div', { class: 'tablewrap' }, h('table', { class: 'stat-table' }, h('thead', {}, h('tr', {}, h('th', {}, 'Buchstabe'), h('th', {}, 'Richtig'), h('th', {}, ''), h('th', {}, 'Versuche'), h('th', {}, 'Geschrieben'))), h('tbody', {}, rows))));
}

/* ----- AI stories (Claude, only in the parents' area) ----- */
let samplePromise = null;
function getSample() {
  if (!samplePromise) {
    const C = window.claude;
    samplePromise = (C && typeof C.use === 'function') ? Promise.resolve().then(() => C.use('sample')).catch(() => null) : Promise.resolve(null);
  }
  return samplePromise;
}
const AI_TOPICS = [['schnee', 'Schnee und Winter in Tirol', 'التلج والشتي'], ['garten', 'Im Garten mit Blumen', 'الجنينة والورد'], ['schloss', 'Ein Schloss und ein Schatz', 'قصر وكنز'], ['meer', 'Am Meer und am Strand', 'البحر والشط'], ['herbst', 'Herbstblätter und Wind', 'ورق الخريف والهوا'], ['backen', 'Backen mit Mama', 'نخبز مع ماما'], ['fest', 'Das Zuckerfest', 'العيد'], ['schule', 'Der erste Schultag', 'أول يوم بالمدرسة'], ['zug', 'Eine Reise mit dem Zug', 'رحلة بالقطار'], ['regen', 'Ein Regentag', 'يوم ماطر']];
const AI_LEVEL_RULE = {
  1: 'Each German sentence has 3 to 5 words. Use only very common, short words (der, die, das, ist, ein, und, ...). Prefer words with the letters m, a, i, o, l, s, e, u, n, r, t.',
  2: 'Each German sentence has 4 to 7 words. Simple, common words; present tense.',
  3: 'Each German sentence has up to 9 words. You may use words with sch, ei, ie, au.',
  4: 'Each German sentence has up to 12 words. One short direct speech is allowed.',
  5: 'Each German sentence has up to 14 words. Up to two short direct speeches are allowed.'
};
const AI_BAD = /hexe|zauber|\bfee\b|feen|magie|monster|geist|gespenst|drache[n]? (?:spuckt|frisst)|schwein|bier|wein\b|musik|gitarre|klavier|trommel|geige|tanz|kuss|küss|waffe|blut|tot\b|sterben/i;
function aiSection() {
  let topic = AI_TOPICS[0][0], lvl = readLevel(), ctl = null;
  const out = h('div', { class: 'ai-out' });
  const go = h('button', { class: 'btn small' }, h('span', { html: ICON.sparkle }), 'Neue Geschichte erfinden');
  const stop = h('button', { class: 'btn soft small', hidden: true }, 'Stopp');
  const listEl = h('div', { class: 'col' });
  const renderList = () => {
    listEl.innerHTML = '';
    (S.aiStories || []).forEach((st, i) => listEl.appendChild(h('div', { class: 'ai-item' }, h('span', { class: 'emoji' }, st.icon), h('b', {}, fillName(st.title)), h('span', { class: 'muted' }, `Stufe ${st.lvl}`),
      h('button', { class: 'rbtn small', html: ICON.trash, 'aria-label': 'Löschen', onclick: () => { S.aiStories.splice(i, 1); Store.save(); renderList(); } }))));
  };
  renderList();
  const sec = psec('Neue Geschichten mit KI', 'قصص جديدة بالذكاء الاصطناعي',
    h('p', { class: 'note' }, 'Claude schreibt eine kurze Geschichte passend zur Lesestufe – mit arabischer Übersetzung. Bilder sind nur Gegenstände, Pflanzen und Essen. Der Name des Kindes wird dabei nicht gesendet; er wird erst in der App eingesetzt. Bitte jede Geschichte kurz selbst ansehen.'),
    fieldSelect('Thema', AI_TOPICS.map(t => [t[0], t[1] + ' – ' + t[2]]), topic, v => topic = v),
    fieldSelect('Lesestufe', [1, 2, 3, 4, 5].map(n => [n, 'Stufe ' + n]), lvl, v => lvl = +v),
    h('div', { class: 'row left' }, go, stop), out, listEl);
  sec.hidden = true;
  getSample().then(sample => {
    if (!sample) return;
    sec.hidden = false;
    stop.onclick = () => { if (ctl) ctl.abort(); };
    go.onclick = async () => {
      const t = AI_TOPICS.find(x => x[0] === topic) || AI_TOPICS[0];
      const allowed = Array.from(SAFE_EMOJI).join('');
      const prompt = `Write a very short, warm German story for a 7-8 year old girl in Austria who is learning to read German. She understands spoken Syrian Arabic but cannot read Arabic.
Topic: ${t[1]}.
Reading level ${lvl} of 5: ${AI_LEVEL_RULE[lvl]}
Rules:
- 5 to 8 pages. Each page: ONE short German sentence ("de", correctly spelled, present tense) and a translation into simple Syrian colloquial Arabic ("ar").
- The main character is the girl. Write her name exactly as {N} in German and {NA} in Arabic. Family members (Mama, Papa, Oma, Opa) may appear.
- Content must suit a Muslim family: kind and calm; no magic, witches, fairies, monsters, ghosts, music or musical instruments, dancing, pork, alcohol, romance, fear or violence.
- Every page has "pic": one or two emoji taken ONLY from this list: ${allowed}
- Add a quiz: a simple German question "q" with Arabic translation "qar", and "o": three answers [German answer, emoji from the list, 1 for the correct one], the correct one first.
Reply with only this JSON:
{"title":"German title","tar":"Arabic title","icon":"emoji","pages":[{"de":"...","ar":"...","pic":"..."}],"quiz":{"q":"...","qar":"...","o":[["...","...",1],["...","..."],["...","..."]]}}`;
      ctl = new AbortController();
      go.disabled = true; stop.hidden = false; out.textContent = 'Claude denkt nach …';
      try {
        const j = await sample.json(prompt, { signal: ctl.signal, cache: false, onText: () => { out.textContent = 'Claude schreibt …'; } });
        const st = cleanAIStory(j, lvl);
        if (!st) { out.textContent = 'Die Geschichte passte nicht zu den Regeln. Bitte noch einmal versuchen.'; }
        else {
          S.aiStories = [st, ...(S.aiStories || [])].slice(0, 12); Store.save(); renderList();
          out.textContent = `Fertig: „${fillName(st.title)}“ – zu finden unter Geschichten.`;
          AE.play('unlock');
        }
      } catch (e) {
        const code = e && e.code;
        out.textContent = code === 'cancelled' ? 'Abgebrochen.' : code === 'not_granted' || code === 'sampling_disabled' ? 'Claude ist hier nicht erlaubt.' : code === 'rate_limited' ? 'Gerade zu viele Anfragen – bitte später nochmal.' : 'Das hat nicht geklappt. Bitte später nochmal versuchen.';
        if (code === 'not_granted' || code === 'sampling_disabled' || code === 'not_declared' || code === 'capability_disabled' || code === 'capability_removed') go.hidden = true;
      } finally { go.disabled = false; stop.hidden = true; ctl = null; }
    };
  });
  return sec;
}
function cleanEmoji(s, fb) {
  const parts = Array.from(String(s || '').replace(/️/g, '')).filter(ch => SAFE_EMOJI.has(ch));
  return parts.slice(0, 3).join('') || fb;
}
function clip(s, n) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, n); }
function cleanAIStory(j, lvl) {
  if (!j || typeof j !== 'object' || !Array.isArray(j.pages)) return null;
  const pages = j.pages.slice(0, 10).map(p => ({ de: clip(p && p.de, 160), ar: clip(p && p.ar, 220), pic: cleanEmoji(p && p.pic, '✨') })).filter(p => p.de && /[a-zäöüß]/i.test(p.de));
  if (pages.length < 3) return null;
  const all = pages.map(p => p.de).join(' ') + ' ' + clip(j.title, 60);
  if (AI_BAD.test(all)) return null;
  const st = { id: 'ai' + Date.now().toString(36), ai: 1, lvl, title: clip(j.title, 48) || 'Neue Geschichte', tar: clip(j.tar, 60), icon: cleanEmoji(j.icon, '📖'), pages };
  const q = j.quiz;
  if (q && Array.isArray(q.o) && q.o.length >= 2) {
    const o = q.o.slice(0, 3).map(x => Array.isArray(x) ? [clip(x[0], 40), cleanEmoji(x[1], '✨'), x[2] ? 1 : 0] : null).filter(x => x && x[0]);
    if (o.length >= 2 && o.filter(x => x[2]).length === 1 && !AI_BAD.test(o.map(x => x[0]).join(' '))) st.quiz = { q: clip(q.q, 90), qar: clip(q.qar, 120), o };
  }
  return st;
}

/* ======================= boot ======================= */
function boot() {
  initDefs();
  Bar.init();
  Profiles.load();
  S = defaults();
  let last = null; try { last = localStorage.getItem('funkelschloss.last'); } catch (e) { }
  const lp = last && Profiles.get(last);
  if (lp) S.world = lp.world || 'eis';
  applyTheme();
  renderScene();
  Perf.init();
  FX.init();
  Nur.init();
  Speech.init();
  Clock.start();
  document.addEventListener('visibilitychange', () => { if (document.hidden) { Speech.stop(); AE.suspend(); Store.now(); } else AE.resume(); });
  window.addEventListener('pagehide', () => Store.now());
  App.go('start');
  Cloud.init();
  if (typeof FamilySave !== 'undefined') FamilySave.init();
  if (typeof siteRoomEntry === 'function') setTimeout(siteRoomEntry, 200);
}

function familyCodeSection() {
  const box = h('div', { class: 'col' });
  const paint = () => {
    box.innerHTML = '';
    const c = FamilySave.code();
    const copy = (txt, msg) => { try { const p = navigator.clipboard && navigator.clipboard.writeText(txt); if (p && p.then) p.then(() => toast(msg), () => toast(txt)); else toast(txt); } catch (e) { toast(txt); } };
    if (c) {
      const link = location.origin + location.pathname + '?family=' + encodeURIComponent(c);
      box.append(
        h('p', { class: 'note' }, '☁️ Verbunden. Der Fortschritt aller Kinder wird automatisch online gesichert und ist auf jedem Gerät mit diesem Code gleich.'),
        h('div', { class: 'famcode' }, c),
        h('div', { class: 'row left' },
          h('button', { class: 'btn soft small', onclick: () => copy(c, 'Code kopiert') }, '📋 Code kopieren'),
          h('button', { class: 'btn soft small', onclick: () => copy(link, 'Link kopiert') }, '🔗 Link für ein anderes Gerät'),
          h('button', { class: 'btn soft small', onclick: async () => { try { const ch = await FamilySave.sync(); toast(ch ? 'Neuer Fortschritt geladen' : 'Alles gesichert ✓'); if (ch) App.go('start'); } catch (e) { toast('Keine Verbindung'); } } }, '🔄 Jetzt abgleichen')),
        h('p', { class: 'note' }, 'Den Code nur der Familie geben.'));
    } else {
      const inp = h('input', { class: 'ar-in code', type: 'text', placeholder: 'FAM-XXXX-XXXX-XXXX', autocapitalize: 'characters' });
      box.append(
        h('p', { class: 'note' }, 'Mit einem Familien-Code geht kein Fortschritt verloren, und jedes Kind findet seine Sterne auf jedem Gerät wieder.'),
        h('div', { class: 'row left' }, h('button', { class: 'btn gold small', onclick: async () => { try { await FamilySave.create(); toast('☁️ Familien-Code erstellt'); paint(); } catch (e) { toast('Keine Verbindung – bitte nochmal'); } } }, '✨ Familien-Code erstellen')),
        h('p', { class: 'note' }, 'Schon einen Code von einem anderen Gerät?'),
        h('div', { class: 'row left' }, inp, h('button', { class: 'btn small', onclick: async () => { try { const ch = await FamilySave.join(inp.value); toast('☁️ Verbunden'); if (ch) { App.go('start'); return; } paint(); } catch (e) { toast(e && e.message === 'code' ? 'Bitte den ganzen Code eingeben' : 'Code nicht gefunden'); } } }, '🔗 Verbinden')));
    }
  };
  paint();
  return psec('Familien-Code (online sichern)', 'كود العيلة', box);
}


/* ======================= shared game helpers ======================= */
function gameScreen(stage, cls) { stage.classList.add('fixed'); stage.innerHTML = ''; const scr = h('div', { class: 'screen game' + (cls ? ' ' + cls : '') }); stage.appendChild(scr); return scr; }
function sayBtn(fn, label, cls) { return h('button', { class: 'rbtn' + (cls ? ' ' + cls : ''), 'aria-label': label || 'Anhören', title: label || 'Anhören', html: ICON.speaker, onclick: e => { e.stopPropagation(); unlockAudio(); AE.play('tap'); fn(); } }); }
function onSize(el, fn) {
  let t = 0; const run = () => { cancelAnimationFrame(t); t = requestAnimationFrame(() => { try { fn(); } catch (e) { console.error(e); } }); };
  if (window.ResizeObserver) { const ro = new ResizeObserver(run); ro.observe(el); App.clean.push(() => ro.disconnect()); }
  App.on(window, 'resize', run); run();
}
function letterWords(l) { return ((LETTERS[l] && LETTERS[l].words) || []).filter(w => W[w]); }
function hlWord(word, l) { const el = wordEl(word); $$('.g', el).forEach(g => { if (g.textContent.toLowerCase() === l) g.classList.add('hl'); }); return el; }
function hlFirst(word) { const el = wordEl(word); const f = el.querySelector('.syl > *'); if (f) f.classList.add('hl'); return el; }
function teamBadge(t) {
  const sp = h('span', { class: 'team force t-' + t });
  if (['ie', 'ee', 'aa', 'oo'].includes(t)) { sp.appendChild(h('span', {}, t[0])); sp.appendChild(h('span', { class: 'fade' }, t.slice(1))); }
  else sp.textContent = t;
  return h('span', { class: 'word hint-team-on' }, sp);
}
function optLetters(l) { const L = LETTERS[l]; return L ? (L.U === l ? l : L.U + ' ' + l) : (cap(l) + ' ' + l); }
const WHY_PIC = { a: '⛺', c: '🍪', f: '🚩', g: '🚪', h: '🪜', i: '🕯️', j: '☂️', k: '🌿', l: '📏', m: '⛰️', o: '💍', p: '🚩', q: '🔍', s: '🛷', t: '🔨', u: '🥣', v: '🍦', w: '🌊', x: '✂️', y: '🌿', z: '⚡', 'ä': '❄️', 'ö': '✨', 'ü': '💧', 'ß': '💞' };
