  const left = h('div', { class: 'col' }, big, acts);
  const why = h('div', { class: 'paper col whybox' });
  const pic = WHY_PIC[l];
  why.appendChild(h('div', { class: 'whyhead' }, pic ? h('span', { class: 'emoji whypic' }, pic) : null, h('p', { class: 'story-txt' }, L.de)));
  why.appendChild(h('button', { class: 'btn soft small', onclick: () => { AE.play('tap'); sayWhy(); } }, h('span', { html: ICON.speaker }), 'Geschichte hören'));
  const chips = h('div', { class: 'wchips' });
