    targetEl.onclick = () => { unlockAudio(); Nur.say([D('Gold mit diesem Buchstaben zählt doppelt.'), D(LL.nm), ...arIf('الدهب اللي عليه هالحرف بيحسب دبل.')], { keep: false }); };
