        c2.lineWidth = Math.max(3, fs * 0.16); c2.strokeStyle = 'rgba(90,55,0,.85)'; c2.strokeText(it.lab, 0, r * 0.05); c2.fillStyle = '#fffbea'; c2.fillText(it.lab, 0, r * 0.05);
