      c2.strokeStyle = 'rgba(255,255,255,.25)'; c2.lineWidth = 1; c2.beginPath(); c2.moveTo(pv.x + 1, pv.y - 2); c2.lineTo(t.x + 1, t.y); c2.stroke();
      c2.save(); c2.translate(t.x, t.y); c2.rotate(-p.th); const cs = clamp(u / 520, 1, 1.6); c2.scale(cs, cs);
      const open = p.item ? 0.12 : p.st === 'out' ? 0.75 : 0.5;
      const metal = c2.createLinearGradient(-14, 0, 14, 0); metal.addColorStop(0, '#5d6670'); metal.addColorStop(0.45, '#eef2f6'); metal.addColorStop(1, '#6b7580');
