      const tl = Math.ceil(tLeft); const tb = timerEl.lastChild; if (tb.textContent !== String(tl)) { tb.textContent = String(tl); timerEl.classList.toggle('low', tLeft <= 10); }
      if (!bg || bg.width !== cv.width) drawBg();
