    const fresh = S.examDay !== today();
    const words = WL.filter(o => !o.tags.includes('irr') && !String(o.e).startsWith('svg:') && o.lvl <= 3 && o.w.length <= 9);
    const pool = Brain.letterPool(2).filter(l => l !== 'ß' && LETTERS[l]);
    const eiie = words.filter(o => /ei|ie/i.test(o.w) && !/ei.*ie|ie.*ei/i.test(o.w));
    const used = new Set();
    const pickW = (f) => { const c = shuffle(words.filter(o => !used.has(o.w) && (!f || f(o)))); const o = c[0] || pick(words); used.add(o.w); return o; };
    const others = (o, n) => shuffle(words.filter(x => x.w !== o.w && x.e !== o.e && !used.has(x.w))).slice(0, n);
    const T = ['hoerbild', 'bildwort', 'buchstabe', 'anlaut', 'gross', 'hoerbild', 'bildwort', 'buchstabe', 'anlaut', 'eiie', 'gross', 'bildwort', 'hoerbild', 'eiie', 'anlaut'];
    const Q = T.map(t => {
      if (t === 'eiie' && eiie.length < 3) t = 'bildwort';
      if (t === 'hoerbild' || t === 'bildwort') { const o = pickW(); return { t, o, opts: shuffle([o, ...others(o, 2)]) }; }
      if (t === 'anlaut') { const o = pickW(x => /^[a-zäöü]/i.test(x.w) && !/^(sch|ch|ei|au|eu|st|sp|qu|pf)/i.test(x.w)); const c = o.w[0].toLowerCase(); const opt = [c, ...shuffle(pool.filter(x => x !== c && x.length === 1)).slice(0, 2)]; return { t, o, c, opts: shuffle(opt) }; }
      if (t === 'eiie') { const o = shuffle(eiie.filter(x => !used.has(x.w)))[0] || eiie[0]; used.add(o.w); const c = /ie/i.test(o.w) ? 'ie' : 'ei'; return { t, o, c, opts: ['ei', 'ie'] }; }
      const l = pick(pool.filter(x => x.length === 1)); const L = LETTERS[l];
      const conf = (L.conf || []).filter(x => LETTERS[x] && x.length === 1);
      const opt = [l, ...shuffle(Array.from(new Set([...conf, ...shuffle(pool)]))).filter(x => x !== l && x.length === 1).slice(0, 3)];
      return { t, l, opts: shuffle(opt) };
    });
    let i = 0, right = 0, stars = 0, wrongNow = 0, locked = false;
    const bar = h('div', { class: 'exam-bar' }), fill = h('i', {}), num = h('b', {});
    bar.append(h('span', { class: 'exam-prog' }, fill), num);
    const play = h('div', { class: 'play exam-play' });
    scr.append(bar, play);
