/* ======================= Nachsprechen ======================= */
GAME_IMPL.nachsprechen = {
  start(stage, ctx) {
    const d = ctx.diff, scr = gameScreen(stage), lvl = readLevel();
    let items;
    if (d === 1) items = shuffle(WL.filter(o => o.lvl <= 2 && !o.tags.includes('irr'))).slice(0, 6).map(o => ({ t: o.w, pic: o.e, ar: o.ar }));
    else if (d === 2) items = shuffle([...shuffle(WL.filter(o => o.lvl <= 3 && o.syl.length >= 2)).slice(0, 3).map(o => ({ t: o.w, pic: o.e, ar: o.ar })), ...shuffle(SATZ.filter(s => s[0] <= 2)).slice(0, 3).map(s => ({ t: s[1], pic: s[2], ar: s[4] }))]);
    else items = shuffle([...SATZ.filter(s => s[0] <= Math.max(3, lvl)).map(s => ({ t: s[1], pic: s[2], ar: s[4] })), ...QUATSCH.filter(q => q[2] && q[0] <= Math.max(3, lvl)).map(q => ({ t: q[1], pic: q[4], ar: q[3] }))]).slice(0, 6);
    const R = makeRound('nachsprechen', items.length, { diff: d, params: ctx.params, ask });
    const play = h('div', { class: 'play' }); scr.append(R.dots, play); R.start();
    function ask(i) {
      const it = items[i]; play.innerHTML = '';
      const sen = sentenceEl(fillName(it.t), tapWord);
      const now = h('div', { class: 'qline nowyou', hidden: true }, 'Jetzt du! Sag es laut.');
      const good = h('button', { class: 'btn gold', hidden: true }, h('span', { html: ICON.star }), 'Geschafft!');
      const again = h('button', { class: 'btn soft' }, h('span', { html: ICON.replay }), 'Nochmal hören');
      const slow = h('button', { class: 'btn soft' }, h('span', { html: ICON.slow }), 'Langsam');
      const read = (o) => karaoke(sen, o).then(ok => { if (!ok) return; now.hidden = false; good.hidden = false; AE.play('chime'); Nur.talk(false); });
      again.onclick = () => { AE.play('tap'); read(); };
      slow.onclick = () => { AE.play('tap'); read({ byWord: true }); };
      good.onclick = () => { unlockAudio(); R.good(good, null, { say: [D(pick(PRAISE)), ...arIf(it.ar)], wait: 1000 }); };
      play.append(h('div', { class: 'prompt' }, picEl(it.pic, 'mid')), h('div', { class: 'paper page' }, sen), now, h('div', { class: 'row' }, again, slow, good));
      Nur.screen = () => readThen(sen, [A(it.ar), D('Jetzt sag es laut nach!'), A('هلّأ قوليها إنتي بصوت عالي!')]);
      const g0 = App.gen; if (i === 0) Nur.say([D('Hör gut zu und sprich laut nach!'), ...arIf('اسمعي منيح وقولي ورا نور بصوت عالي!')]).then(ok => { if (ok && App.alive(g0)) read(); });
      else App.later(() => read(), 350);
    }
  }
};

/* ======================= Geschichten ======================= */
const STORY_NEED = { 1: 0, 2: 15, 3: 40, 4: 80, 5: 120 };
GAME_IMPL.geschichten = { start(stage, ctx) { libraryView(stage); } };
function libraryView(stage) {
  Speech.stop(); Bar.setBack(null); stage.className = ''; stage.innerHTML = ''; stage.scrollTop = 0;
  const scr = h('div', { class: 'screen' }, h('h1', { class: 'h1' }, 'Geschichten'), h('p', { class: 'sub ar' }, 'اختاري قصة – القصص بتصير أطول شوي شوي'));
  const books = h('div', { class: 'books' });
  [...(S.aiStories || []), ...STORIES].forEach(st => {
    const need = st.ai ? 0 : (STORY_NEED[st.lvl] || 0), locked = !S.unlockAll && S.earned < need;
    const card = h('button', { class: 'bookcard' + (locked ? ' locked' : '') },
      picEl(st.icon), h('b', {}, fillName(st.title)), h('span', { class: 'ar muted' }, fillName(st.tar || '')),
      h('span', { class: 'lvl' }, [1, 2, 3, 4, 5].map(n => h('i', { class: n <= st.lvl ? 'on' : '' }))),
      S.storiesDone[st.id] ? h('span', { class: 'badge' }, '✓ gelesen') : st.ai ? h('span', { class: 'badge' }, 'Neu') : null,
      locked ? h('span', { class: 'badge lockb' }, h('span', { html: ICON.lock }), String(need - S.earned), h('span', { class: 'ls', html: ICON.star })) : null);
    card.onclick = () => {
      unlockAudio();
      if (locked) { AE.play('no'); Nur.say([D('Diese Geschichte geht bald auf. Sammle noch ein paar Sterne!'), ...arIf('هالقصة بتنفتح قريباً. جمّعي كم نجمة كمان!')]); return; }
      AE.play('page'); chooseMode(stage, st);
    };
    books.appendChild(card);
  });
  scr.appendChild(books); stage.appendChild(scr);
  Nur.screen = () => [D('Hier sind deine Geschichten. Tippe auf ein Buch.'), A('هون القصص تبعك. اضغطي على أي كتاب لتقريه أو تسمعيه.'), D('Die Bücher mit dem Schloss gehen mit mehr Sternen auf.'), A('الكتب اللي عليها قفل بتنفتح لما تجمعي نجوم أكتر.')];
  Nur.say([D('Welche Geschichte möchtest du lesen?'), ...arIf('أي قصة بدك تقري؟')]);
}
function chooseMode(stage, st) {
  const b1 = h('button', { class: 'modebtn' }, h('span', { html: ICON.book }), h('b', {}, 'Ich lese selbst'), h('small', { class: 'ar' }, 'بقرا لحالي'));
  const b2 = h('button', { class: 'modebtn' }, h('span', { html: ICON.speaker }), h('b', {}, 'Lies mir vor'), h('small', { class: 'ar' }, 'اقريلي إنتي يا نور'));
  b1.onclick = () => { AE.play('tap'); Sheet.onClose = null; Sheet.close(); reader(stage, st, 'self'); };
  b2.onclick = () => { AE.play('tap'); Sheet.onClose = null; Sheet.close(); reader(stage, st, 'listen'); };
  Sheet.open(h('div', { class: 'modes' }, b1, b2), { title: fillName(st.title), icon: ICON.book });
  Nur.say([D('Liest du selbst, oder soll ich vorlesen?'), ...arIf('بتقري لحالك، ولا بدك ياني اقريلك؟')]);
}
function reader(stage, st, mode) {
  Speech.stop(); Bar.setBack(() => libraryView(stage)); Voice.preload(['story-' + st.id]);
  const scr = gameScreen(stage, 'reader-screen');
  const pages = st.pages, idx = {}; pages.forEach((p, i) => { if (p.id) idx[p.id] = i; });
  let i = 0; const hist = [], solved = {};
  const rd = h('div', { class: 'reader' }); scr.appendChild(rd);
  function render() {
    Speech.stop(); const p = pages[i]; rd.innerHTML = '';
    const isLast = i === pages.length - 1 && !p.go;
    const page = h('div', { class: 'paper page' }); let sen = null;
    const nextB = h('button', { class: 'btn' + (isLast ? ' gold' : '') }, isLast ? 'Fertig' : 'Weiter', h('span', { html: ICON.next }));
    if (p.type === 'gap') {
      const word = p.word, pos = word.indexOf(p.miss); let gapEl = null;
      const box = h('div', { class: 'slots' });
      Array.from(word).forEach((c, k) => { const s = k === pos ? (gapEl = h('span', { class: 'slot next' }, '?')) : h('span', { class: 'slot filled' }, c); box.appendChild(s); });
      const opts = h('div', { class: 'opts small3' }); let wrong = 0, okB = null;
      shuffle(p.opts).forEach(o => {
        const b = h('button', { class: 'opt' }, o); if (o === p.miss) okB = b;
        b.onclick = () => {
          unlockAudio(); if (solved[i]) return;
          if (o === p.miss) { solved[i] = true; gapEl.textContent = o; gapEl.classList.add('filled'); gapEl.classList.remove('next'); b.classList.add('ok'); AE.play('ok'); FX.burstAt(b, { n: 20 }); addStars(1, b); nextB.classList.add('glowbtn'); Nur.say([D(cap(word.toLowerCase()) + '!'), ...arIf('برافو! هلّأ الكلمة كاملة.')]); }
          else { wrong++; b.classList.remove('no'); void b.offsetWidth; b.classList.add('no'); AE.play('no'); Nur.say([D('Hör genau:'), D(cap(word.toLowerCase()))], { keep: false }); if (wrong >= 2) okB.classList.add('hint'); }
        };
        opts.appendChild(b);
      });
      sen = sentenceEl(fillName(p.de), tapWord);
      page.append(sen, box, opts);
    } else if (p.type === 'choice') {
      sen = sentenceEl(fillName(p.de), tapWord);
      const ch = h('div', { class: 'choice' });
      p.choices.forEach(c => { const b = h('button', { class: 'opt choicebtn' }, picEl(c.pic), h('span', { class: 'otxt' }, c.de)); b.onclick = () => { unlockAudio(); AE.play('door'); solved[i] = { go: idx[c.go] }; go(idx[c.go]); }; ch.appendChild(b); });
      page.append(sen, ch); nextB.hidden = true;
    } else { sen = sentenceEl(fillName(p.de), tapWord); page.appendChild(sen); }
    const tr = h('div', { class: 'tr ar', hidden: true }, fillName(p.ar || ''));
    page.appendChild(tr);
    const prevB = h('button', { class: 'btn soft icon', html: ICON.back, 'aria-label': 'Zurück', disabled: !hist.length });
    const readB = h('button', { class: 'btn soft' }, h('span', { html: ICON.speaker }), 'Vorlesen');
    const arB = h('button', { class: 'btn soft' }, h('span', { class: 'arl' }, 'ع'), 'Arabisch');
    prevB.onclick = () => { if (!hist.length) return; AE.play('page'); i = hist.pop(); render(); };
    readB.onclick = () => { unlockAudio(); AE.play('tap'); readAll(false); };
    arB.onclick = () => { unlockAudio(); AE.play('tap'); tr.hidden = false; Nur.say([A(fillName(p.ar || ''))], { keep: false }); };
    nextB.onclick = () => { unlockAudio(); next(); };
    function readAll(auto) { if (!sen) return; karaoke(sen).then(ok => { if (ok && auto && S.arAuto && S.arIntro && p.ar) { tr.hidden = false; Nur.say([A(fillName(p.ar))], { keep: false }); } }); }
    rd.append(h('div', { class: 'pic' }, picEl(p.pic)), page, h('div', { class: 'navrow' }, prevB, readB, arB, nextB), h('div', { class: 'pageno' }, `${i + 1} / ${pages.length}`));
    Nur.screen = () => ({ run: tok => { tr.hidden = !p.ar; const arp = p.ar ? [A(fillName(p.ar))] : []; return sen ? karaoke(sen).then(ok => { if (ok && arp.length) return Nur.say(arp, { keep: false, bubble: true, ex: tok }); }) : Nur.say(arp, { keep: false, ex: tok }); } });
    if (p.fx) App.later(() => AE.play(p.fx), 420);
    if (mode === 'listen') App.later(() => readAll(true), 650);
  }
  function go(n) { hist.push(i); i = n; AE.play('page'); render(); }
  function next() {
    const p = pages[i];
    if (p.type === 'gap' && !solved[i]) { AE.play('no'); Nur.say([D('Welcher Buchstabe fehlt?'), ...arIf('أي حرف ناقص؟')], { keep: false }); return; }
    if (p.type === 'choice') { Nur.say([D('Welche Tür nimmst du?'), ...arIf('أي باب بتختاري؟')], { keep: false }); return; }
    if (p.go && idx[p.go] != null) go(idx[p.go]);
    else if (i + 1 < pages.length) go(i + 1);
    else finish();
  }
  function finish() {
    Speech.stop(); rd.innerHTML = '';
    if (!st.quiz) { celebrate(); return; }
    const q = st.quiz, sen = sentenceEl(fillName(q.q), tapWord);
    const opts = h('div', { class: 'opts' }); let okB = null, wrong = 0;
    shuffle(q.o).forEach(o => {
      const b = h('button', { class: 'opt' }, picEl(o[1]), h('span', { class: 'otxt' }, fillName(o[0]))); if (o[2]) okB = b;
      b.onclick = () => {
        unlockAudio();
        if (o[2]) { if (b.classList.contains('ok')) return; b.classList.add('ok'); AE.play('ok'); FX.burstAt(b, { n: 30 }); Nur.say([D(fillName(o[0]) + '!'), D(pick(PRAISE))], { keep: false }); App.later(celebrate, 1500); }
        else { wrong++; b.classList.remove('no'); void b.offsetWidth; b.classList.add('no'); AE.play('no'); if (wrong >= 2) okB.classList.add('hint'); }
      };
      opts.appendChild(b);
    });
    rd.append(h('div', { class: 'pic' }, picEl('❓')), h('div', { class: 'paper page' }, sen, h('div', { class: 'tr ar', hidden: !S.arIntro }, fillName(q.qar || ''))), opts);
    Nur.screen = () => readThen(sen, [A(fillName(q.qar || '')), ...q.o.map(o => D(fillName(o[0]) + '?'))]);
    karaoke(sen).then(ok => { if (ok && S.arIntro && q.qar) Nur.say([A(fillName(q.qar))], { keep: false }); });
  }
  function celebrate() {
    const first = !S.storiesDone[st.id]; S.storiesDone[st.id] = 1; Store.save();
    Daily.mark('geschichten');
    rd.innerHTML = '';
    const bk = h('div', { class: 'bigbook', html: gameIcon('geschichten') });
    rd.append(bk, h('h1', { class: 'h1' }, 'Geschichte geschafft!'), h('p', { class: 'sub' }, fillName(st.title)),
      h('div', { class: 'row' },
        h('button', { class: 'btn', onclick: () => { AE.play('tap'); i = 0; hist.length = 0; Object.keys(solved).forEach(k => delete solved[k]); render(); } }, h('span', { html: ICON.replay }), 'Nochmal lesen'),
        h('button', { class: 'btn soft', onclick: () => { AE.play('tap'); libraryView(stage); } }, h('span', { html: ICON.book }), 'Andere Geschichte')));
    AE.play('win'); FX.confetti(90); addStars(first ? 5 : 2, bk);
    Nur.screen = () => [D('Du hast die Geschichte geschafft,'), NM(), A('خلّصتي القصة يا'), NMA(), A('برافو!'), D('Willst du sie nochmal lesen, oder eine andere?'), A('بدك تقريها مرة تانية، ولا قصة تانية؟')];
    Nur.say([D('Du hast die Geschichte gelesen,'), NM(), D(pick(PRAISE)), ...arOn(A('خلّصتي القصة يا'), NMA(), A('برافو عليكي!'))]);
    App.later(() => afterRound(), 2600);
  }
  render();
}

