function glyph(ch, x, y, s, cls) {
  const st = ST[ch]; if (!st) return '';
  return `<g transform="translate(${x} ${y}) scale(${s})"><g class="lg ${cls || ''}">` + st.map((p, i) => p.dot ? `<circle class="s${i}" cx="${p.dot[0]}" cy="${p.dot[1]}" r="7"/>` : `<path class="s${i}" d="${strokePath(p)}"/>`).join('') + '</g></g>';
}
