      const k = st.target.key; st.seen[k] = st.seen[k] || { t: st.target.t, ok: !st.wrongNow }; st.seen[k].t = st.target.t;
      st.target = null; st.tm = null; App.later(() => { if (!st.target) pickTarget(m); }, 420);
