    for (const m of st.ms) {
      if (m.dead) continue;
      m.bob += dt * (m.D.lane === 'a' ? 1.4 : 7); if (m.hitT > 0) m.hitT -= dt; if (m.slowT > 0) m.slowT -= dt; if (m.ramT > 0) m.ramT -= dt; if (m.throwT > 0) m.throwT -= dt;
      if (frozen) continue;
      const spd = m.D.sp * st.spd * (M.portK || 1) * (m.slowT > 0 ? 1 - m.slowK : 1) * (m.D.boss && !m.on ? 4 : 1);
      if (m.state === 'walk') {
        m.x -= spd * dt;
        if (m.D.lane === 'g') { m.dustT -= dt; if (m.dustT <= 0) { m.dustT = 0.18; const snowy = S.world === 'eis' || S.world === 'polar'; P({ k: 'smoke', x: X(m.x + m.w * 0.35), y: M.gy - M.u * 0.05, vx: M.u * 0.4, vy: -M.u * 0.3, r: M.u * 0.12, gr: M.u * 0.4, life: 0.7, c: snowy ? '235,242,250' : '170,140,105', a: 0.35 }); } }
        if (m.D.act === 'throw' && m.x <= M.stopKat) { m.state = 'throw'; m.act = 0.6; }
        if (m.D.act === 'drop' && m.x <= M.cx + 0.3) { m.state = 'hover'; m.act = 0.8; }
        if (m.D.act === 'ram' && m.x - m.w / 2 <= M.front) { m.x = M.front + m.w / 2; m.state = 'ram'; m.act = 0.3; }
        if (m.x < -m.w) m.dead = true;
      } else if (m.state === 'ram') { m.act -= dt; if (m.act <= 0) { m.act = m.D.every; m.ramT = 0.22; hitWall(m.D.dmg, X(M.front), M.gy - X(Math.min(m.h, 1.2)) * 0.55); } }
      else if (m.state === 'throw') { m.act -= dt; if (m.act <= 0) { m.act = m.D.every; mudShot(m); } }
      else if (m.state === 'hover') { m.act -= dt; if (m.act <= 0) { m.act = m.D.every; mudShot(m, true); } }
      if (m.D.steam) { m.steamT -= dt; if (m.steamT <= 0) { m.steamT = 0.35 + Math.random() * 0.3; const top = m.y - X(m.h); m.D.steam.forEach(sp => smoke(X(m.x - m.w / 2 + m.w * sp[0]), top + X(m.h) * sp[1], 1, '245,245,245')); } }
    }
