      if (s.kind === 'bomb') { s.x = s.x0 + (s.x1 - s.x0) * k; s.y = s.y0 + (s.y1 - s.y0) * k * k; }
      else { s.x = s.x0 + (s.x1 - s.x0) * k; s.y = s.y0 + (s.y1 - s.y0) * k - Math.sin(k * Math.PI) * s.arc; }
      if (s.kind === 'letter' && Math.random() < 0.8) P({ k: 'spark', x: s.x, y: s.y, vx: (Math.random() - 0.5) * M.u * 0.6, vy: (Math.random() - 0.5) * M.u * 0.6, g: 0, life: 0.35, c: pick(['#fff3b0', '#ffd34d', '#ffffff']), s: M.u * 0.05 });
      if (s.kind === 'water' && Math.random() < 0.5) P({ k: 'dot', x: s.x, y: s.y, vx: 0, vy: 0, g: M.u * 3, life: 0.35, c: '#bfe9ff', s: M.u * 0.04 });
      if (s.kind === 'gust' && Math.random() < 0.7) P({ k: 'swirl', x: s.x, y: s.y + (Math.random() - 0.5) * M.u * 0.6, vx: M.u * 2, vy: 0, life: 0.5, r: M.u * (0.2 + Math.random() * 0.25) });
