      add(h('b', {}, '🌐 Online mit der Familie'), h('small', {}, FUNKEL_SITE ? 'Ohne Konto: einer erstellt einen Raum, die anderen geben den Code ein oder öffnen den Link.' : 'Hier in Claude: einer erstellt einen Raum, die anderen geben den Code ein. Mitspielen kann dein eigenes Konto (Handy + iPad) und wer über „Teilen“ eingeladen ist.'),
        h('div', { class: 'ar-row' }, nameIn), h('div', { class: 'ar-row' }, mk), h('div', { class: 'ar-row' }, codeIn, jn), err);
