      const segL = h('div', { class: 'on-segs small' }); [[1, 'Leicht'], [2, 'Mittel'], [3, 'Profi']].forEach(([v, tx]) => { const b = h('button', { class: 'on-seg' + ((Net.botLvl || 2) === v ? ' on' : ''), type: 'button' }, tx); b.onclick = () => { Net.botLvl = v; AE.play('tap'); paint(); }; segL.appendChild(b); });
